#
# stand-revision-verdict.sh — вердикт о стенде НЕСЁТ ревизию проверяемого.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПРЕДМЕТ (kacho#2180)
#
# Расходятся ДЕРЕВО и СОБРАННОЕ ИЗ НЕГО. Ручка стоит в окружении пода, значение
# верное, профиль безупречен — а процесс отказывает так, будто её нет: читателя
# нет в КОНКРЕТНОЙ СБОРКЕ. Наблюдалось дважды за один заход выкатки (#2177):
# образ на стенде был собран на 7 ч 16 мин раньше коммита, вводившего и ручку, и
# её читателя; карта манифестов порождена деревом до переезда якоря кластера.
#
# Ни рендер, ни гейт дерева, ни декларативная проба значений этого не поймают
# BY CONSTRUCTION: все трое судят ДЕРЕВО, а расходятся дерево и собранное.
# Единственный, кто может ответить, — работающий контейнер, и спросить его надо
# ТАМ ЖЕ, где выносится вердикт о его поведении.
#
# ЛОВИЛОСЬ ЭТО И ПРЕЖДЕ — `deploy/scripts/stand-provenance.sh` умеет спросить. Но
# его надо ПОЗВАТЬ, и никто не звал: три работы конвейера, чья краснота
# цитировалась в трёх задачах линии, мерили ревизию старше головы на шесть часов.
# Поэтому предмет здесь — не способность спросить, а то, что вопрос задаётся САМ.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОЧЕМУ ОДИН ВЛАДЕЛЕЦ, А НЕ ТЕЛО ШАГА В КАЖДОЙ РАБОТЕ
#
# Работ подъёма три. Развилка, размноженная по работам, расходится молча — она
# уже расходилась: делегирование классификации подъёма было у одной из четырёх
# (см. deploy/scripts/assert-stand-precondition-wiring.py, звено 2). Здесь та же
# форма: тело шага зовёт ЕДИНСТВЕННОГО владельца, а владелец знает про исходы.
#
# ─────────────────────────────────────────────────────────────────────────────
# ЧТО ЭТОТ СКРИПТ ДЕЛАЕТ С ИСХОДАМИ — И ПОЧЕМУ НЕ КРАСНЕЕТ НИ НА ОДНОМ
#
#   стенда нет      → причина уже названа шагом подъёма; печатаем и выходим 0
#   0 сходится      → строка в сводку: вердикт ниже относится к ЭТОМУ дереву
#   1 не установлена→ ГРОМКО в сводку: вердикт ниже ревизии НЕ несёт. Отметку НЕ
#                     ставим: это граница инструмента (образ мог быть собран не
#                     нами), и глушить ею прогон значило бы завести способ
#                     сделать работу вечно-«не выполнившейся» одной опечаткой
#   2 не опрошен    → то же: сказать вслух, не глушить
#   3 РАСХОДИТСЯ    → отметка `STAND_PRECONDITION_UNMET=1`: судить стенд, который
#                     исполняет ЧУЖОЕ дерево, значит вынести вердикт не о том
#                     предмете. Это «не выполнилось», а НЕ находка, — отказ здесь
#                     честнее зелёного
#
# КРАСНЫМ НЕ СТАНОВИТСЯ НИ ОДИН: этот шаг вердикта о продукте не выносит. Красное
# рядом с настоящим вердиктом дало бы два разных ответа на один вопрос.
#
# ─────────────────────────────────────────────────────────────────────────────
# ГРАНИЦА, НАЗВАННАЯ ЧЕСТНО
#
# Отметка гасит шаги, идущие НИЖЕ. Там, где вердикт выносит сам шаг подъёма
# (боевая посадка), гасить уже нечего — вердикт вынесен. Для такой работы
# остаётся форма «провенанс печатается рядом с вердиктом», и это ровно то, чего
# требует предикат снятия задачи; строка сводки говорит об этом прямо.
#
# ─────────────────────────────────────────────────────────────────────────────
# КАК ЗВАТЬ
#
#   bash "$GITHUB_WORKSPACE/.github/scripts/stand-revision-verdict.sh" "<чей стенд>"
#
# Способность различать исходы доказана инъекцией: `--self-test` подменяет ровно
# два факта (ответ провенанса и наличие стенда) и требует РАЗНЫХ исходов.

set -uo pipefail

ROOT="${GITHUB_WORKSPACE:-$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)}"
PRESENCE="$ROOT/.github/scripts/stand-present-or-explain.sh"
PROVENANCE="$ROOT/deploy/scripts/stand-provenance.sh"
PROVENANCE_MK="$ROOT/provenance.mk"

# say — в журнал работы И в сводку прогона. Вердикт, лежащий только в журнале,
# ничем не отличается от невызванного: журналы планового прогона не читает никто.
say() {
  printf '%s\n' "$*"
  [ -n "${GITHUB_STEP_SUMMARY:-}" ] && printf '%s\n' "$*" >> "$GITHUB_STEP_SUMMARY"
  return 0
}

# expected_revision — ОДНО объявление величины, прочитанное, а не вычисленное.
# `--eval` заводит цель на лету: в самом provenance.mk цели нет намеренно (она
# стала бы целью по умолчанию у каждого включающего Makefile).
expected_revision() {
  # `$(OCI_IMAGE_REVISION)` — переменная MAKE, а не оболочки. Одинарные кавычки
  # здесь обязательны: раскрой её bash, в make уехала бы пустая строка, и ядро
  # честно ответило бы «сравнивать не с чем». Пояснение стоит ПЕРЕД директивой —
  # токен, не имеющий вида ключ=значение, обрывает её разбор.
  # shellcheck disable=SC2016
  make -f "$PROVENANCE_MK" -s --no-print-directory \
       --eval='__kacho_print_revision: ; @printf "%s\n" "$(OCI_IMAGE_REVISION)"' \
       __kacho_print_revision 2>/dev/null
}

main() {
  local label="${1:-стенд}"

  if ! bash "$PRESENCE" "$label"; then
    say "### провенанс стенда «$label» — НЕ СНЯТ"
    say "Кластера нет: причина названа шагом подъёма. Ревизию спрашивать не у кого."
    return 0
  fi

  # `unknown` — то, что provenance.mk подставляет, когда git не ответил. Это
  # НЕ величина: сравнив с ней, мы получили бы расхождение у каждого контейнера
  # и заглушили прогон по своей же слепоте. Отличать надо здесь, а не по коду
  # провенанса: там тот же отказ выглядел бы как «стенд не опрошен», хотя стенд
  # ответил, а не прочитано было наше собственное объявление.
  local expect; expect="$(expected_revision)"
  case "$expect" in
    ""|unknown|unknown-dirty)
      say "### провенанс стенда «$label» — ожидаемая ревизия НЕ ПРОЧИТАНА"
      say "Объявление \`provenance.mk\` не отдало величину (получено: «$expect»):"
      say "сравнивать не с чем. Вердикт ниже ревизии проверяемого НЕ несёт —"
      say "это граница, а не «сошлось»."
      return 0 ;;
  esac

  local out rc
  out="$(bash "$PROVENANCE" --namespace "${KACHO_NAMESPACE:-kacho}" --expect "$expect" 2>&1)"
  rc=$?

  say "### провенанс стенда «$label»"
  say '```'
  printf '%s\n' "$out"
  [ -n "${GITHUB_STEP_SUMMARY:-}" ] && printf '%s\n' "$out" >> "$GITHUB_STEP_SUMMARY"
  say '```'

  case "$rc" in
    0)
      say "Ревизия установлена у каждого контейнера продукта и СХОДИТСЯ с \`$expect\` —"
      say "вердикт о поведении стенда относится к этому дереву."
      ;;
    3)
      say "**РАСХОЖДЕНИЕ: стенд исполняет ДРУГОЕ дерево.** Ожидалось \`$expect\`."
      say "Вердикт о поведении такого стенда относится не к тому предмету, поэтому"
      say "прогон отказывается судить: это «не выполнилось», а не находка."
      if [ -n "${GITHUB_ENV:-}" ]; then
        echo "STAND_PRECONDITION_UNMET=1" >> "$GITHUB_ENV"
        say "Отметка \`STAND_PRECONDITION_UNMET=1\` поставлена — шаги ниже пропускаются."
      else
        say "Отметку ставить некуда (\`GITHUB_ENV\` не задан) — сказано только словами."
      fi
      ;;
    1)
      say "Ревизия установлена НЕ у всех — вердикт ниже её не несёт."
      say "Это граница инструмента (образ мог быть собран не нами), а не находка:"
      say "прогон не глушится, но и «сошлось» здесь не утверждается."
      ;;
    *)
      say "Стенд НЕ опрошен (код $rc) — вердикт ниже ревизии проверяемого не несёт."
      say "Это «не выполнилось» на стороне провенанса, а не «ревизия сходится»."
      ;;
  esac
  return 0
}

# ─────────────────────────────────────────────────────────────────────────────
# САМОПРОВЕРКА — доказательство инъекцией в ОБЕ стороны, без кластера.
#
# Подменяются РОВНО ДВА факта: есть ли стенд и что ответил провенанс. Тело выше
# исполняется НАСТОЯЩЕЕ: проба, читающая его глазами, доказывала бы лишь то, что
# оно написано.
self_test() {
  local work; work="$(mktemp -d)"
  # shellcheck disable=SC2064
  trap "rm -rf '$work'" EXIT
  mkdir -p "$work/.github/scripts" "$work/deploy/scripts"
  local pass=0 fail=0

  ok()  { pass=$((pass + 1)); printf '  OK   %s\n' "$*"; }
  bad() { fail=$((fail + 1)); printf '  ПРОВАЛ %s\n' "$*"; }

  cat > "$work/.github/scripts/stand-present-or-explain.sh" <<'STUB'
#!/usr/bin/env bash
[ -f "$KACHO_SELFTEST_WORK/stand-present" ] && exit 0
echo "стенда нет (заглушка)"
exit 1
STUB
  cat > "$work/deploy/scripts/stand-provenance.sh" <<'STUB'
#!/usr/bin/env bash
cat "$KACHO_SELFTEST_WORK/prov.out"
exit "$(cat "$KACHO_SELFTEST_WORK/prov.rc")"
STUB
  printf 'OCI_IMAGE_REVISION := deadbeefdeadbeefdeadbeefdeadbeefdeadbeef\n' > "$work/provenance.mk"
  chmod +x "$work/.github/scripts/stand-present-or-explain.sh" "$work/deploy/scripts/stand-provenance.sh"
  export KACHO_SELFTEST_WORK="$work"

  # run <есть ли стенд> <код провенанса> <вывод провенанса> → печатает сводку,
  # а код возврата и наличие отметки складывает в файлы рядом.
  run() {
    : > "$work/summary"; : > "$work/env"
    if [ "$1" = "есть" ]; then : > "$work/stand-present"; else rm -f "$work/stand-present"; fi
    printf '%s\n' "$2" > "$work/prov.rc"
    printf '%s\n' "$3" > "$work/prov.out"
    GITHUB_WORKSPACE="$work" GITHUB_STEP_SUMMARY="$work/summary" GITHUB_ENV="$work/env" \
      bash "${BASH_SOURCE[0]}" "проба" >/dev/null 2>&1
    printf '%s' "$?" > "$work/rc"
  }
  marked() { grep -q 'STAND_PRECONDITION_UNMET=1' "$work/env"; }
  summary() { cat "$work/summary"; }

  echo "1. КОНТРОЛЬ: ревизия сходится — сводка несёт ВЕЛИЧИНУ, отметки нет"
  run есть 0 "сходится у 8, РАСХОДИТСЯ у 0"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked \
     && [[ "$(summary)" == *"deadbeefdeadbeef"* ]] && [[ "$(summary)" == *"СХОДИТСЯ"* ]]; then
    ok "вердикт несёт ревизию, прогон не заглушен"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "2. ВНЕСЁН ДЕФЕКТ #2180: стенд исполняет другое дерево — ОТМЕТКА и «не выполнилось»"
  run есть 3 "РАСХОЖДЕНИЕ: контейнер исполняет 1111111, а прогон запущен из deadbeef"
  if [ "$(cat "$work/rc")" = 0 ] && marked \
     && [[ "$(summary)" == *"не выполнилось"* ]] && [[ "$(summary)" == *"РАСХОЖДЕНИЕ"* ]]; then
    ok "отметка поставлена, исход назван третьей категорией, шаг не покраснел"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "3. ЗАКОННЫЙ БЛИЗНЕЦ: ревизия не установлена (код 1) — сказано вслух, но НЕ заглушено"
  run есть 1 "НЕ установлена у 2"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked && [[ "$(summary)" == *"НЕ у всех"* ]]; then
    ok "граница названа, прогон не превращён в вечно-«не выполнившийся»"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "4. ЗАКОННЫЙ БЛИЗНЕЦ: стенд не опрошен (код 2) — «не сошлось» и «не спрашивали» различены"
  run есть 2 "ОТКАЗ: кластер не отвечает"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked && [[ "$(summary)" == *"НЕ опрошен"* ]]; then
    ok "код 2 не выдан за совпадение"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "5. ЗАКОННЫЙ БЛИЗНЕЦ: стенда нет вовсе — причина уже названа шагом подъёма"
  run нет 0 "неважно"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked && [[ "$(summary)" == *"НЕ СНЯТ"* ]]; then
    ok "эха чужого отказа нет, отметка не задвоена"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "6. ВНЕСЁН ДЕФЕКТ: объявление величины пусто — «сравнивать не с чем», а не «сошлось»"
  : > "$work/provenance.mk"
  run есть 0 "сходится у 8"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked && [[ "$(summary)" == *"НЕ ПРОЧИТАНА"* ]]; then
    ok "пустое объявление названо границей, а не совпадением"
  else
    bad "код $(cat "$work/rc"); сводка: $(summary)"
  fi

  echo "7. ВНЕСЁН ДЕФЕКТ: git не ответил — величина «unknown», и это НЕ ревизия"
  # Без этой оси «unknown» уехало бы в сравнение, разошлось бы с КАЖДЫМ
  # контейнером и заглушило прогон по нашей же слепоте — то есть отказ выглядел
  # бы находкой о стенде.
  printf 'OCI_IMAGE_REVISION := unknown\n' > "$work/provenance.mk"
  run есть 0 "сходится у 8"
  if [ "$(cat "$work/rc")" = 0 ] && ! marked && [[ "$(summary)" == *"НЕ ПРОЧИТАНА"* ]] \
     && [[ "$(summary)" == *"unknown"* ]]; then
    ok "«unknown» названо непрочитанным объявлением, а не расхождением стенда"
  else
    bad "код $(cat "$work/rc"); отметка: $(marked && echo есть || echo нет); сводка: $(summary)"
  fi

  echo "итог самопроверки: прошло $pass, провалено $fail"
  [ "$fail" -eq 0 ]
}

if [ "${1:-}" = "--self-test" ]; then
  self_test
  exit $?
fi
main "$@"
